:root {
  --custom-reasoning-text: "𝔇𝔢𝔞𝔱𝔥 𝔑𝔬𝔱𝔢";
  --custom-load-more: "人们天真的以为犯错只需要祈祷/忏悔";
  --custom-input-placeholder: "写下你的忏悔，或祈祷...";
  --white-base: #FFFFFF;
  --white-off: #F5F5F5;
  --gray-lightest: #EEEEEE;
  --gray-light: #E0E0E0;
  --gray-mid: #BDBDBD;
  --gray-deep: #9E9E9E;
  --black-soft: #2C2C2C;
  --black-light: #424242;
  --gray-text-light: #616161;
  --underline-color: #9E9E9E;
  --quote-border: #BDBDBD;
  --avatar-top: 55px;
  --avatar-left: 110px;
  --avatar-rotate: -11deg;
  --avatar-scale: 2.5;
  --name-top: 132px;
  --name-left: 12px;
  --name-rotate: 0deg;
  --name-scale: 0.7;
  --id-top: 3px;
  --id-left: 32%;
  --id-rotate: -11deg;
  --id-scale: 0.7;
  --id-translate-x: -50%;
  --timer-top: 18px;
  --timer-left: 35%;
  --timer-rotate: -11deg;
  --timer-scale: 0.7;
  --timer-translate-x: -50%;
  --token-top: 30px;
  --token-left: 39%;
  --token-rotate: -11deg;
  --token-scale: 0.7;
  --token-translate-x: -50%;
}

body {
  background-color: var(--white-base);
  color: var(--black-soft);
}

body, .mes_text, .mes .mes_text, .drawer-content, .options-content, 
input, textarea, button, .mes_block, .name_text, .mes_timer, .tokenCounterDisplay {
  color: var(--black-soft);
}

u, ins {
  text-decoration: underline;
  text-decoration-color: var(--underline-color);
  text-underline-offset: 3px;
  color: var(--black-light);
}

em, i {
  color: var(--gray-text-light);
  font-style: italic;
}

q, blockquote {
  border-left: 3px solid var(--quote-border) !important;
  padding-left: 10px !important;
  margin: 0 4px;
  font-style: normal;
  background-color: var(--white-off);
  border-radius: 0 8px 8px 0;
}

q::before, blockquote::before {
  content: none !important;
}

code {
  background-color: #D3D3D3 !important;
  color: #1E1E1E !important;
  padding: 2px 6px !important;
  border-radius: 0 !important;
  font-family: monospace;
}

pre {
  background-color: #000000 !important;
  padding: 12px !important;
  border-radius: 0 !important;
  color: #FFFFFF !important;
  overflow-x: auto;
}

pre code {
  background-color: #D3D3D3 !important;
  color: #1E1E1E !important;
  padding: 2px 6px !important;
  border-radius: 0 !important;
  font-family: monospace;
}

.drawer-content,
#table_drawer_content,
.options-content {
  background-color: var(--white-off) !important;
  border-color: var(--gray-light) !important;
  box-shadow: none !important;
}

#top-settings-holder {
  background-color: var(--white-base);
  background-image: none;
  border: 1px solid var(--gray-light);
  border-radius: 16px;
  box-shadow: none;
}

#top-bar {
  border-radius: 16px !important;
  background-color: transparent !important;
  box-shadow: none !important;
  border: none !important;
}

#top-settings-holder .drawer-icon::before {
  content: '✟' !important;
  font-size: 20px;
  color: var(--black-soft);
  transition: transform 0.2s;
  display: inline-block;
}

#top-settings-holder .drawer-icon:hover::before {
  transform: scale(1.1);
}

#top-settings-holder .drawer-icon.closedIcon::before,
#top-settings-holder .drawer-icon.openIcon::before {
  content: '✟' !important;
}

#send_form {
  background-color: var(--white-base);
  background-image: none;
  border-radius: 24px !important;
  border: none !important;
  outline: 1px solid var(--gray-light);
  outline-offset: -1px;
  padding: 8px 12px;
  box-shadow: none;
  position: relative;
}

#send_textarea {
  border-radius: 20px !important;
  background-color: var(--gray-lightest) !important;
  border-color: var(--gray-mid) !important;
  color: var(--black-soft);
}

#options_button::before { content: '✞' !important; }
#extensionsMenuButton::before { content: '✠' !important; }
#quick-reply-rocket-button i::before { content: '✙' !important; }
#send_but::before { content: '✚' !important; }
#mes_stop i::before { content: '✛' !important; }

#send_form [class*="fa-"]::before {
  font-size: 18px;
  color: var(--black-soft);
  transition: transform 0.2s;
}

#send_form [class*="fa-"]:hover::before {
  transform: scale(1.1);
}

.qr--buttons {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition: opacity 0.3s ease-in-out, visibility 0.3s ease-in-out, max-height 0.5s ease, transform 0.5s ease;
}

#send_form:focus-within .qr--buttons {
  opacity: 1;
  visibility: visible;
  max-height: 120px;
  transform: translateY(0);
  pointer-events: auto;
}

#qr--bar {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  pointer-events: none;
  transition: opacity 0.3s ease-in-out, visibility 0.3s ease-in-out, max-height 0.3s ease;
}

#send_form:focus-within #qr--bar,
.qr--buttons.active #qr--bar {
  opacity: 1;
  visibility: visible;
  max-height: 200px;
  pointer-events: auto;
}

#chat {
  background-image: url('https://iili.io/BR4K05F.jpg') !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
  backdrop-filter: none !important;
}

.mes {
  width: 450px !important;
  max-width: 90vw !important;
  background: var(--white-base) !important;
  border: none !important;
  outline: 1px solid var(--gray-light);
  outline-offset: 0;
  border-radius: 0 !important;
  margin: 16px auto !important;
  padding: 0 !important;
  box-shadow: none !important;
  position: relative;
  display: flex !important;
  flex-direction: column !important;
  overflow: visible !important;
}

.mes[is_user="false"] {
  margin-bottom: 32px !important;
  padding-bottom: 17px !important;
}

.mes::before {
  content: "" !important;
  display: block !important;
  width: 100% !important;
  padding-bottom: 56.25% !important;
  background-image: url('https://iili.io/BRWkIKg.png') !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  flex-shrink: 0 !important;
  position: relative !important;
  z-index: 2 !important;
  margin: 0 !important;
}

.mes .avatar {
  position: absolute !important;
  top: var(--avatar-top) !important;
  left: var(--avatar-left) !important;
  z-index: 1 !important;
  transform: rotate(var(--avatar-rotate)) scale(var(--avatar-scale)) !important;
  transform-origin: top left !important;
}

.mes .avatar img {
  width: 48px !important;
  height: 48px !important;
  border-radius: 0 !important;
  outline: none !important;
  box-shadow: none !important;
}

.mes .name_text {
  position: absolute !important;
  top: var(--name-top) !important;
  left: var(--name-left) !important;
  z-index: 3 !important;
  transform: rotate(var(--name-rotate)) scale(var(--name-scale)) !important;
  transform-origin: top left !important;
  font-size: 1rem !important;
  font-weight: bold;
  background: linear-gradient(135deg, #808080, #FFFFFF) !important;
  -webkit-background-clip: text !important;
  background-clip: text !important;
  color: transparent !important;
  white-space: nowrap;
}

.mes .name_text::before {
  content: "// " !important;
  background: linear-gradient(135deg, #808080, #FFFFFF) !important;
  -webkit-background-clip: text !important;
  background-clip: text !important;
  color: transparent !important;
}

.mes .mesIDDisplay,
#chat .mes .mesIDDisplay {
  position: absolute !important;
  top: var(--id-top) !important;
  left: var(--id-left) !important;
  transform: translateX(var(--id-translate-x)) rotate(var(--id-rotate)) scale(var(--id-scale)) !important;
  z-index: 3 !important;
  color: rgba(255, 255, 255, 0.8) !important;
  font-size: 0.75rem !important;
  white-space: nowrap;
  background: transparent !important;
}

.mes .mes_timer,
#chat .mes .mes_timer {
  position: absolute !important;
  top: var(--timer-top) !important;
  left: var(--timer-left) !important;
  transform: translateX(var(--timer-translate-x)) rotate(var(--timer-rotate)) scale(var(--timer-scale)) !important;
  z-index: 3 !important;
  color: rgba(255, 255, 255, 0.8) !important;
  font-size: 0.75rem !important;
  white-space: nowrap;
  background: transparent !important;
}

.mes .tokenCounterDisplay,
#chat .mes .tokenCounterDisplay {
  position: absolute !important;
  top: var(--token-top) !important;
  left: var(--token-left) !important;
  transform: translateX(var(--token-translate-x)) rotate(var(--token-rotate)) scale(var(--token-scale)) !important;
  z-index: 3 !important;
  color: rgba(255, 255, 255, 0.8) !important;
  font-size: 0.75rem !important;
  white-space: nowrap;
  background: transparent !important;
}

.mes .mes_block {
  margin: 12px 16px 16px 16px !important;
  padding: 0 !important;
  max-width: calc(100% - 32px) !important;
  word-wrap: break-word !important;
  overflow-wrap: break-word !important;
  word-break: break-word !important;
}

.mes .mes_text,
.mes_text p {
  line-height: 1.5;
  max-width: 100%;
  overflow-x: hidden;
}

.mes.last_mes .mesAvatarWrapper {
  padding-bottom: 0 !important;
}

.mes .mes_text {
  width: 100%;
  padding: 0;
}

.mes:hover {
  transform: none;
  box-shadow: none;
}

.mes[is_user="true"],
.mes[is_user="false"] {
  outline: 1px solid var(--gray-light);
}

.mes_button, .extraMesButtons > div {
  cursor: pointer;
  transition: opacity 0.2s ease-in-out;
  filter: drop-shadow(0px 0px 0px #ffffff) !important;
  color: black !important;
  opacity: 0.4 !important;
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
  background-color: transparent;
}

::-webkit-scrollbar-track {
  background-color: var(--gray-lightest);
  border-radius: 10px;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(to bottom, #b0b0b0, #6e6e6e);
  border-radius: 10px;
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  background: transparent !important;
}

input[type="range"]::-webkit-slider-runnable-track {
  height: 6px;
  background: linear-gradient(to right, #b0b0b0, #555555);
  border-radius: 3px;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  height: 18px;
  width: 18px;
  background-color: var(--black-soft);
  border-radius: 50%;
  margin-top: -6px;
  cursor: pointer;
  transition: transform 0.1s;
}

input[type="range"]:hover::-webkit-slider-thumb {
  transform: scale(1.2);
}

#nonQRFormItems {
  position: relative;
}

#send_textarea::placeholder {
  color: transparent !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: var(--custom-input-placeholder);
  color: #8a8a8a;
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-size: 0.6em;
  line-height: 1;
  pointer-events: none;
  white-space: nowrap;
  background: var(--gray-lightest);
  padding: 2px 12px;
  border-radius: 30px;
  backdrop-filter: blur(2px);
  z-index: 100;
}

#saved_regex_scripts,
#saved_scoped_scripts,
#saved_preset_scripts,
#global-script-list,
#character-script-list {
  margin-right: 80px !important;
}

.regex-script-label.flex-container,
.flex-container .script-item {
  flex-wrap: wrap !important;
  padding: 8px 12px;
  border-radius: 12px;
  margin-bottom: 8px;
  background: var(--white-off);
  border: 1px solid var(--gray-light);
}

.regex-script-label.flex-container .regex_script_name,
.script-item .script-item-name {
  flex-basis: 100%;
  white-space: normal;
  font-weight: 600;
  color: var(--black-soft);
}

.regex-script-label.flex-container > .flex-container.flexnowrap,
.script-item .script-item-control {
  width: 100%;
  justify-content: flex-start;
  gap: 8px;
}

#show_more_messages {
  font-size: 0 !important;
  display: block;
  padding: 8px 20px;
  margin: 20px auto;
  width: fit-content;
  background-color: var(--white-base);
  border: 1px solid var(--gray-mid);
  border-radius: 40px;
  cursor: pointer;
  transition: all 0.25s ease;
  box-shadow: none;
}

#show_more_messages::before {
  content: var(--custom-load-more);
  font-size: 0.85rem !important;
  color: var(--black-soft);
  font-weight: 500;
  letter-spacing: 0.3px;
}

#show_more_messages:hover {
  background-color: var(--gray-lightest);
  border-color: var(--gray-deep);
  transform: translateY(-1px);
}

#show_more_messages:hover::before {
  color: #000000;
}

.mes_reasoning_summary {
  list-style: none;
  cursor: pointer;
  display: flex !important;
  align-items: center;
}

.mes_reasoning_arrow {
  display: none !important;
}

.mes_reasoning_header {
  background: #000000 !important;
  border: 1px solid #333333 !important;
  border-radius: 20px;
  padding: 4px 14px;
  transition: all 0.2s;
}

.mes_reasoning_summary:hover .mes_reasoning_header {
  background: #1a1a1a !important;
  border-color: #666666;
}

.mes_reasoning_header_title {
  font-size: 0 !important;
}

.mes_reasoning_header_title::before {
  content: var(--custom-reasoning-text);
  font-size: 0.8rem;
  color: #FFFFFF !important;
  font-weight: 500;
}

.mes_reasoning {
  margin-top: 8px;
  padding: 12px;
  background-color: #000000 !important;
  border-left: 3px solid #ffffff !important;
  border-radius: 12px;
  color: #F0F0F0 !important;
  font-size: 0.8rem;
  line-height: 1.5;
  max-height: 200px;
  overflow-y: auto;
}

.hotswap.avatars_inline {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  padding-right: 15px;
  scrollbar-width: thin;
}

.hotswap.avatars_inline::-webkit-scrollbar {
  height: 4px;
}

.hotswap.avatars_inline::-webkit-scrollbar-thumb {
  background: var(--gray-mid);
  border-radius: 10px;
}

@media (max-width: 768px) {
  .hotswap.avatars_inline {
    overflow: auto;
  }
}

hr {
  border-color: var(--gray-light);
  margin: 16px 0;
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user settings-block h4,
.standoutHeader {
  background-image: none;
  border: none;
  background-color: #808080 !important;
  color: #ffffff !important;
}

select {
  background-color: #000000 !important;
  color: #ffffff !important;
  border: 1px solid #cccccc;
}

.text_pole {
  background-color: #000000 !important;
  color: #ffffff !important;
  border: 1px solid #cccccc;
}

input[type="range"]::-webkit-slider-runnable-track {
  background: #808080 !important;
}
input[type="range"]::-moz-range-track {
  background: #808080 !important;
}

input:not(input[type="range"], input[type="checkbox"]) {
  background-color: #000000 !important;
  color: #ffffff !important;
  border: 1px solid #cccccc;
}

input[type="checkbox"] {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  background-color: #000000 !important;
  border: 1px solid #ffffff;
  outline: none;
  box-shadow: none;
  cursor: pointer;
}
input[type="checkbox"]:checked {
  background-color: #000000 !important;
  border-color: #ffffff;
  position: relative;
}
input[type="checkbox"]:checked::before {
  content: "✓";
  display: block;
  color: #ffffff;
  font-size: 14px;
  text-align: center;
  line-height: 18px;
  width: 100%;
  height: 100%;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span {
  filter: none;
}

.completion_prompt_manager_header {
  color: black !important;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  filter: none;
}

.text_pole,
select,
input[type="text"],
input[type="number"],
input[type="search"],
#settingsSearch,
.popup textarea,
#description_textarea,
#firstmessage_textarea,
.edit_textarea.mdHotkeys,
.reasoning_edit_textarea,
.select2-container--default .select2-selection--single,
.select2-container--default .select2-selection--multiple {
