.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
  background-color: #000000 !important;
  color: #ffffff !important;
  border: none;
}

.inline-drawer-header .inline-drawer-icon {
  color: #ffffff !important;
}

.fa-solid.killSwitch.fa-toggle-on,
.fa-solid.killSwitch.fa-toggle-off {
  color: black !important;
}

#temp_counter_openai,
#openai_max_context_counter,
#top_k_counter_openai,
#top_p_counter_openai {
